import { describe, it } from "vitest";

describe("MHPCO claim office", () => {
  // quote: premium = item base premiums (+ item surcharges) + policy-wide modifiers + 5 G fee
  it.todo("quote with empty item list -> premium 5 G (only the processing fee)");
  it.todo("quote for a plain sword, newcomer -> 100 base + 10 first insurance + 5 fee = 115 G");
  it.todo("quote for a plain amulet, newcomer -> 60 + 6 + 5 = 71 G");
  it.todo("quote for a plain staff, newcomer -> 80 + 8 + 5 = 93 G");
  it.todo("quote for a plain potion, newcomer -> 40 + 4 + 5 = 49 G");
  it.todo("quote for 2 runes -> 50 G base premium -> 50 + 5 + 5 = 60 G");
  it.todo("quote for 3 runes -> block 60 G base premium -> 60 + 6 + 5 = 71 G");
  it.todo("quote for 4 runes -> no block, 100 G base premium -> 100 + 10 + 5 = 115 G");
  it.todo("quote for 7 runes -> 175 G base -> 197.5 G rounded up in MHPCO's favor to 198 G");
  it.todo("quote for 2 runes + 1 moonstone -> no block (different types), 75 G base -> 87.5 rounded up to 88 G");
  it.todo("quote for a cursed steel sword (enchantment 3), newcomer -> 100 + 50 curse + 10 first = 160 + 5 = 165 G");
  it.todo("quote for a cursed sword + plain amulet -> 160 base + 50 curse (sword only) + 16 first + 5 = 231 G");
  it.todo("quote for a sword with exactly enchantment 5 -> 100 + 30 high enchantment + 10 + 5 = 145 G");
  it.todo("quote for a sword, customer with exactly 2 years -> 100 - 20 loyalty + 10 + 5 = 95 G");
  it.todo("second quote in a scenario for a sword, newcomer -> 100 + 10 first - 15 follow-up + 5 = 100 G");
  it.todo("CLI: schema example on stdin -> stdout {results:[{premium:59},{payout:100,remainingCap:1100}]}");
  it.todo("CLI: quote with unknown item type broomstick -> non-zero exit, error on stderr, no results on stdout");
  // claim: per damage (reimbursement - 100 deductible), total capped at remaining 2x insurance sum
  it.todo("claim on a steel sword (enchantment 3), damage 500 G -> payout 400 G, remainingCap 1600 G");
  it.todo("claim on a rune, damage 200 G -> payout 100 G, remainingCap 400 G (cap 2 x 250)");
  it.todo("claim on a plain amulet, damage 200 G -> payout 100 G, remainingCap 1100 G (cap 2 x 600)");
  it.todo("claim on a plain staff, damage 200 G -> payout 100 G, remainingCap 1500 G (cap 2 x 800)");
  it.todo("claim on a plain potion, damage 200 G -> payout 100 G, remainingCap 700 G (cap 2 x 400)");
  it.todo("claim on a moonstone, damage 200 G -> payout 100 G, remainingCap 400 G (cap 2 x 250)");
  it.todo("claim: dragon attack on insured sword 500 G and amulet 300 G -> payout 600 G (deductible per item), remainingCap 2600 G");
  it.todo("claim on a steel sword with enchantment 9, damage 1000 G -> payout 400 G (50 % then deductible)");
  it.todo("claim on a steel sword with enchantment 9, damage 901 G -> 350.5 G rounded down in MHPCO's favor to 350 G");
  it.todo("claim with damage 50 G on a sword -> payout 0 G (reading: the deductible never makes a payout negative)");
  it.todo("two successive 1500 G claims on a sword -> first payout 1400 G remainingCap 600 G, second payout 600 G remainingCap 0 G");
  it.todo("CLI: claim with two sword damages but only one sword insured -> non-zero exit, error on stderr, whole claim rejected");
  it.todo("CLI: claim with damage amount -200 -> non-zero exit, error on stderr");

  describe("verification", () => {
    it.todo("quote for 3 runes + 3 moonstones -> two separate blocks, 120 G base -> 132 + 5 = 137 G -- per-type grouping, block");
    it.todo("quote for a sword with enchantment 4 -> no high-enchantment surcharge -> 115 G -- enchantment 5 threshold");
    it.todo("quote for a cursed sword with enchantment 4 -> only curse surcharge -> 165 G -- curse, enchantment threshold");
    it.todo("quote for a cursed sword with exactly enchantment 5 -> both surcharges: 100 + 50 + 30 + 10 + 5 = 195 G -- curse, enchantment");
    it.todo("quote for a sword, customer with 1 year -> no loyalty discount -> 115 G -- loyalty threshold");
    it.todo("quote for sword + amulet, customer with 2 years -> loyalty on policy base: 160 - 32 + 16 + 5 = 149 G -- loyalty, multi-item");
    it.todo("integration: 3-year customer's second quote, cursed steel sword enchantment 7 -> 160 G -- all modifiers");
    it.todo("claim on a steel sword with enchantment 8, dragon material, damage 1000 G -> payout 400 G -- enchantment clause");
    it.todo("claim on a dragon-material sword with enchantment 9, damage 1000 G -> payout 400 G (50 % wins) -- enchantment clause");
    it.todo("claim on a dragon-material sword with enchantment 5, damage 800 G -> payout 700 G (full reimbursement) -- standard reimbursement");
    it.todo("claim on a policy with two swords, both damaged 500 G and 300 G -> payout 600 G, remainingCap 3400 G (cap 4000) -- per-item deductible, insurance sum");
    it.todo("claim on a cursed sword, damage 500 G -> payout 400 G, remainingCap 1600 G (cap from unmodified value 2000) -- cap");
    it.todo("claim on sword + 3 runes, sword damage 500 G -> payout 400 G, remainingCap 3100 G (insurance sum 1750, cap 3500) -- rune value, sum");
    it.todo("CLI: claim with amulet damage when only a sword is insured -> non-zero exit, error on stderr -- damage matching");
    it.todo("CLI: claim with unknown damage item type -> non-zero exit, error on stderr -- damage matching");
  });
});

